import{z as A,x as m,o as r,c as p,q as s,j as t,D as e,d as E,s as i,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Memorizing Transformers","description":"","frontmatter":{"title":"Memorizing Transformers","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/memorizing-transformers.md","filePath":"llm/memorizing-transformers.md","lastUpdated":1791063341000}'),B={name:"llm/memorizing-transformers.md"};function d(k,a,h,f,g,F){const n=m("Mermaid");return r(),p("div",null,[a[2]||(a[2]=s('<h1 id="memorizing-transformers" tabindex="-1">Memorizing Transformers <a class="header-anchor" href="#memorizing-transformers" aria-label="Permalink to &quot;Memorizing Transformers&quot;">​</a></h1><div class="epigraph"><p>不必把新知识写进权重；把过去的键值存进不可微的外部记忆，用近似 k 近邻取回，模型就能在推理时当场记住刚读到的定义。</p><footer>—— Wu、Rabe、Hutchins、Szegedy，Memorizing Transformers，ICLR 2022</footer></div><p>Google 的 Yuhuai Wu、Markus N. Rabe、DeLesley Hutchins 与 Christian Szegedy 在 ICLR 2022 提出 Memorizing Transformer：解码器主体仍是局部稠密注意力，靠近顶部的一层额外对外部记忆做近似 \\(k\\)NN。记忆里是先前子序列的 \\((k,v)\\)，梯度不回传到记忆，因此可以复用上一步已经算好的键值，把缓存做到 131k–262k token 仍装得进单卡 TPU。论文在 C4 长文档、arXiv、PG-19、GitHub、Isabelle 形式化定理上显示：记忆越大，困惑度越低；代码与数学上，测试时新出现的函数与引理定义会被检索到。本篇按这篇 2022 年原文写。它比 RoPE 延窗更早，问的是「注意力当检索」，而不是「相位出界」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Transformer 的有效上下文受稠密注意力长度限制，小说跨章指代、代码跨文件引用、证明引用早先引理，都需要看见很远的精确 token，而不是平均值。把事实存进权重要数十万步才能改完；若注意力能把定义写成键值、稍后用查询取回，则阅读即学习。已有长程方案或做池化（远距被平均），或做稀疏（子集不一定含定义），或像 Transformer-XL 只缓存上一段前缀。</p><p>Wu 等人要的是：远距仍然返回<strong>精确</strong>的值向量，而不是摘要；记忆大到 \\(10^5\\) 量级时训练步时仍可接受。这两条一起，迫使记忆不可微——若对记忆反传，每一步都要用当前参数重算全部历史键值，规模立刻垮掉。</p><p><span class="marginnote">直觉类比：池化像把整章书压成一句摘要，稀疏注意力像只允许看抽查的几页；kNN 记忆则像在书页间夹满书签，需要时翻回原页读原句。跨章指代要的是「原句」，所以前两者不够。</span></p><h3 id="不可微是为了规模-不是为了偷懒" tabindex="-1">不可微是为了规模，不是为了偷懒 <a class="header-anchor" href="#不可微是为了规模-不是为了偷懒" aria-label="Permalink to &quot;不可微是为了规模，不是为了偷懒&quot;">​</a></h3><p>键值是参数的函数。可微记忆意味着历史必须用<strong>当前</strong> \\(\\theta\\) 重算，否则梯度对不上。不可微则允许把上一步局部上下文的 \\((k,v)\\) 追加进 FIFO，旧文档清空。分布会偏移：记忆里的键来自略旧的参数。论文把这当成可接受的代价，并用实验证明 \\(k\\)NN 仍有用。这与后来 Retrieval 增强（REALM、RAG）不同：那些检索的是静态文本片段；这里检索的是同一文档里模型自己写过的内部表示。</p><p><span class="marginnote">kNN 近似注意力，不替换 FFN。Lample 等人用 kNN 换前馈层，是另一条轴。本文的记忆里是过去 token 的键值，不是学出来的键库。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>长文档切成 512 token 的子序列，<strong>按文档顺序</strong>送入，不打乱，类似 XL。局部上下文用滑窗因果掩码，并缓存上一步的键值当 512 前缀，使每个 token 有 512 的稠密邻域。外部记忆每头保存先前 \\(M\\) 对 \\((k,v)\\)，容量满则丢最旧。</p><h3 id="knn-增强层" tabindex="-1">kNN 增强层 <a class="header-anchor" href="#knn-增强层" aria-label="Permalink to &quot;kNN 增强层&quot;">​</a></h3><p>堆叠中靠上的一层（实验里 12 层模型常用第 9 层）除局部稠密注意力外，用同一组查询对记忆做近似 kNN，返回每条查询自己的 top-\\(k\\)（常用 \\(k=32\\)）。对检索到的键做点积、softmax、加权值，与标准注意力相同，只是每条查询的键集合不同。局部结果 \\(V_c\\) 与记忆结果 \\(V_m\\) 用每头一个标量门混合：</p> \\[g=\\sigma(b_g),\\qquad V_a = V_m \\odot g + V_c \\odot (1-g). \\]<p>\\(b_g\\) 可学习。实验观察到多数头最终几乎只看记忆。局部用 T5 相对位置偏置；检索到的记忆<strong>不加</strong>位置偏置——作者引用长程相对位置不重要、T5 也会把远距打进同一桶的观察。TPU 上的近似 kNN 约 90% recall；CPU/GPU 可用 Faiss 或 ScaNN。</p><p>训练时每个 batch 里不同文档各有一份记忆，文档边界清空。模型可在比训练更大的 \\(M\\) 上推理：小记忆训出的权重，加大 \\(M\\) 仍能降 PPL。记忆从 1536 增到 262144，质量单调变好。同尺寸下加 8k 记忆的增益，可以超过把模型放大 5 倍以上（原文图 1 的主张）。</p><p><span class="marginnote">算一笔账看清 \\(k\\) 的意义：\\(k=32\\) 意味着每条查询只精确读记忆里 32 个位置的值向量，而不是全部 262144 条。这就是为什么「262k 记忆」不等于「262k 稠密上下文」——远处只有 top-\\(k\\) 条进入计算。</span></p>',18)),(r(),t(l,null,{default:e(()=>[i(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%BD%93%E5%89%8D%20512%20token%22%5D%20--%3E%20L%5B%22%E5%B1%80%E9%83%A8%E7%A8%A0%E5%AF%86%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20X%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20MEM%5B%22%E5%A4%96%E9%83%A8%E8%AE%B0%E5%BF%86%20FIFO%22%5D%20--%3E%20KNN%5B%22%E8%BF%91%E4%BC%BC%20kNN%20top-k%22%5D%0A%20%20Q%20--%3E%20KNN%0A%20%20KNN%20--%3E%20G%5B%22%E6%AF%8F%E5%A4%B4%E9%97%A8%E6%8E%A7%E6%B7%B7%E5%90%88%22%5D%0A%20%20L%20--%3E%20G%0A%20%20G%20--%3E%20Y%5B%22%E5%B1%82%E8%BE%93%E5%87%BA%22%5D%0A%20%20L%20--%3E%20MEM%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[E("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"机制是把注意力拆成「邻域精确 softmax」与「全局内容寻址」。门控让头选择自己是局部句法头还是检索头。因为取回的是未压缩的值，函数体、引理陈述可以原样进入残差流，这是相对 Compressive Transformer 的关键差别。不可微导致记忆键略旧，但查询与键仍在同一层表示空间里，只要参数缓慢变化，近邻关系大致保持。近似 kNN 漏掉约 10% 真近邻，表现为偶发漏检，而不是系统性平均。",-1)),(r(),t(l,null,{default:e(()=>[i(n,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E7%9C%8B%E8%A7%81%2010%20%E4%B8%87%20token%20%E5%89%8D%E7%9A%84%E5%AE%9A%E4%B9%89%22%5D%20--%3E%20HOW%7B%22%E8%AE%B0%E5%BF%86%E5%8F%AF%E5%BE%AE%E5%90%97%EF%BC%9F%22%7D%0A%20%20HOW%20--%3E%7C%22%E5%8F%AF%E5%BE%AE%22%7C%20RE%5B%22%E5%8E%86%E5%8F%B2%E9%94%AE%E5%80%BC%E9%A1%BB%E7%94%A8%E5%BD%93%E5%89%8D%E5%8F%82%E6%95%B0%E9%87%8D%E7%AE%97%22%5D%0A%20%20RE%20--%3E%20COST%5B%22%E6%AF%8F%E6%AD%A5%E6%88%90%E6%9C%AC%E9%9A%8F%E5%8E%86%E5%8F%B2%E9%95%BF%E5%BA%A6%E7%88%86%E7%82%B8%22%5D%0A%20%20COST%20--%3E%20DEAD%5B%22%E8%A7%84%E6%A8%A1%E5%9E%AE%E6%8E%89%22%5D%0A%20%20HOW%20--%3E%7C%22%E4%B8%8D%E5%8F%AF%E5%BE%AE%22%7C%20FIF%5B%22%E5%A4%8D%E7%94%A8%E4%B8%8A%E4%B8%80%E6%AD%A5%E7%AE%97%E5%A5%BD%E7%9A%84%E9%94%AE%E5%80%BC%E5%85%A5%20FIFO%22%5D%0A%20%20FIF%20--%3E%20CHEAP%5B%22%E7%BC%93%E5%AD%98%E5%8F%AF%E5%A0%86%E5%88%B0%20262k%20%E6%9D%A1%EF%BC%8C%E5%8D%95%E5%8D%A1%E8%A3%85%E4%B8%8B%22%5D%0A%20%20CHEAP%20--%3E%20SHIFT%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E9%94%AE%E6%9D%A5%E8%87%AA%E7%95%A5%E6%97%A7%E5%8F%82%E6%95%B0%EF%BC%8C%E5%88%86%E5%B8%83%E7%95%A5%E5%81%8F%E7%A7%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">常见误区：以为「不可微」是设计偷懒。恰恰相反——可微记忆要求每个训练步都用当前参数重算全部历史键值（否则梯度对不上），成本随历史长度爆炸；不可微才让缓存复用成为可能。分布偏移是为规模付的租金。</span></p><p>代码与 Isabelle 上的定性分析表明：当生成处需要一个刚定义的名字，检索到的键往往落在定义处。这被用来支持「测试时阅读即记忆」：权重不变，记忆里多了这一篇的 \\((k,v)\\)，行为就变。C4 等通用网上文本增益较小，因为远距精确引用更少；结构化长依赖越强，记忆越值钱。</p><p><span class="marginnote">没有位置偏置的远距检索，模型分不清「定义在一万 token 前」还是「在八百 token 前」，只分内容相似。需要顺序敏感的任务时，应把块索引编码进键，或回到有相对偏置的方案。原文认为对书与代码这不是主矛盾。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>只增强一层，不是每层都 kNN，以控制延迟。记忆按头存，体积是 \\(M\\times\\) 头数 \\(\\times\\) 维。文档级 FIFO 不能跨语料共享成世界知识库——那是 RAG 的事；本文记忆是<strong>当前长文档的工作记忆</strong>。分布偏移在长时间训练后是否累积，原文用「仍有效」回答，没有给理论保证。decode 逐步追加键值时，近似索引要能动态插入，生产实现比训练时的块状 TPU 近似更麻烦。</p><p>与 2023–2024 延窗论文的关系：Memorizing Transformer 不修 RoPE，甚至主要不是 RoPE 模型；它修的是可见集。PI/YaRN 让相位能算到 32k，仍然对全部 32k 做二次注意力。要把窗口做到 256k 且只精确读少数位置，kNN 记忆与 Landmark 是更早的轴。不要把「262k 记忆」写成「262k 稠密上下文」——局部仍是 512+XL 前缀，远处只有 top-\\(k\\) 条。</p><p><span class="marginnote">门控与 token 内容无关，只是每头一个偏置。作者提到改成内容门是 trivial 扩展。若某些头应随查询在局部与记忆之间切换，现公式做不到，这是 2022 年简化。</span></p><h3 id="评测读法" tabindex="-1">评测读法 <a class="header-anchor" href="#评测读法" aria-label="Permalink to &quot;评测读法&quot;">​</a></h3><p>应看 PPL 对 \\(M\\) 的曲线是否单调，以及是否能把训练 \\(M\\) 外推到更大推理 \\(M\\)。代码与定理任务上要有「定义在前文、使用在后文」的探针，否则降 PPL 可能只来自更好的局部 XL。与放大模型比参数效率时，把记忆容量的存储成本算进去：记忆不是免费的，只是不进梯度图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Memorizing Transformers 在局部稠密层之外，用不可微外部记忆上的近似 kNN 扩展有效上下文。</li><li>梯度不回传记忆，从而复用历史键值，单设备可到 131k–262k 条。</li><li>每头标量门混合局部与检索；远距不加位置偏置。</li><li>记忆越大 PPL 越好，且可在更大记忆上零样本外推；代码与数学能用上测试时新定义。</li><li>远距是 top-\\(k\\) 精确值，不是摘要，也不是满窗口 softmax。</li><li>出处：Wu、Rabe、Hutchins、Szegedy，<em>Memorizing Transformers</em>，ICLR 2022，arXiv:2203.08913。对照 Dai 等 Transformer-XL（2019）、Rae 等 Compressive Transformer（2020）、Mohtashami 等 Landmark Attention（2023）。</li></ul>',11))])}const u=A(B,[["render",d]]);export{c as __pageData,u as default};
